.console-body .strip .wire-socket{
  display:flex;align-items:center;justify-content:center;gap:5px;
  flex:1;max-width:100%;min-width:0;height:24px;
  border:1px solid #45616f;border-radius:3px;
  color:#a7c4cf;background:linear-gradient(#314653,#182e39 48%,#162a34);
  box-shadow:inset 0 1px #a9deef2a,0 1px #0009;
  font:600 9px/1 Arial,sans-serif!important;
  cursor:pointer;user-select:none;
}

/* V12 physical console wire strip: FL send-switch affordances, but original ArSonMix tooling.
   53px collapsed row stays visible; FX elastic and hardware fader are untouched. */
.wire-mode-label{font:600 9px/1 Arial,Helvetica,sans-serif;color:#a4c7d2;white-space:nowrap;margin-left:5px}

.console-body .strip .wire-tray .wire-disconnect{
 flex:0 0 17px;width:17px;height:21px;min-width:17px;padding:0;
 font:600 14px/18px Arial,sans-serif!important;color:#a8c4cb;
 border:1px solid #47616a;border-radius:3px;background:linear-gradient(#34444c,#172932);
 box-shadow:inset 0 1px #a3bed31c;cursor:pointer;
}

/* V13 physical routing bay — no old DAW send form in mixer strips.
   Compact: 80px, Expanded: 160px; +80px fold is balanced by P0 fader
   budget on expand, preserving the rack's four legible insert rows. */
.console-body.wire-routing-v13.collapsed-send{}

.console-body.wire-routing-v13 .strip .wire-deck{
 display:flex;position:relative;flex:1 1 0!important;min-height:0!important;
 width:100%;flex-direction:column;gap:2px;align-items:flex-start;
 padding:5px 6px 2px;
 background:
  linear-gradient(90deg,#b7e3eb0c,transparent 6%,transparent 92%,#b7e3eb08),
  repeating-linear-gradient(90deg,transparent 0 19px,#b6d5de09 19px 20px),
  linear-gradient(#0f202a,#0e1c25 52%,#0a1820);
 border-bottom:1px solid #354c58;
 overflow:hidden;
}

/* A carefully restrained physical edge is fine; broad face gradients and
   worn-metal zebra strokes are not. */

/* V14.1 physical hierarchy: three upper modules can close independently.
   SEND close is a TRUE 23px folded header, not a tiny still-active patch bay.
   The source/destination graph belongs to state, not to the SVG or DOM nodes. */
.console-body.wire-routing-v13.collapsed-send{
 --send-h:23px!important;
}

/* No odd visual leftover: the collapsed compartment is just a tidy header,
   with its disclosure affordance on the rail. */
.console-body.wire-routing-v13.collapsed-send .strip .wire-section{
 background:#172732!important;
 border-top:1px solid #3e55603d!important;
 box-shadow:inset 0 1px #ffffff08!important;
}

/* V15 original physical patch connectors: filled bronze/silver OUT jack, recessed
   hollow IN socket. Calm console design; route highlight only on actual intent.
   Compact always keeps the wires visible; expanded has more cable canvas. */
.console-body.wire-routing-v15.collapsed-send{}

.console-body.wire-routing-v15 .wire-node-out,
.console-body.wire-routing-v15 .wire-node-in{
 display:flex!important;flex-direction:column!important;align-items:center!important;
 justify-content:center!important;
 flex:0 0 28px!important;width:28px!important;min-width:28px!important;
 height:28px!important;min-height:28px!important;
 border-radius:50%!important;
 font:600 18px/17px 'Segoe UI Symbol',Arial,sans-serif!important;
 user-select:none;-webkit-user-select:none;touch-action:none;
 position:relative;box-sizing:border-box;z-index:7;
}

/* V16: the WIRE graph is an upper compartment. When SEND is folded
   the sockets and cable illustration are invisible, leaving only a
   clean 23px disclosure row; model fan-out remains untouched. */
.console-body.wire-routing-v15.collapsed-send{--send-h:23px!important}

/* Wire V17: fixed four-column hardware patch. Never reflow on route changes. */
.console-body.wire-routing-v15 .strip .wire-tray,.console-body.wire-routing-v15 .strip .wire-tray.linked{
 display:grid!important;grid-template-columns:24px 28px 22px!important;gap:4px!important;
 align-items:center!important;justify-content:center!important;
 height:35px!important;min-height:35px!important;max-height:35px!important;
 padding:3px 2px!important;box-sizing:border-box!important;
}

/* V23 DAW folded-bay correction: a 23px electronic link LED, NEVER the
   truncated live patch jack/knob or numeric send badges. Physical rack geometry
   and approved FX/WIRE/I/O rail icons are unchanged. */
.console-body.wire-routing-v15.collapsed-send .strip .send-section.wire-section{
 display:flex!important;flex-direction:column!important;align-items:stretch!important;
 justify-content:center!important;
 height:23px!important;min-height:23px!important;max-height:23px!important;
 padding:0!important;overflow:hidden!important;
}

/* V24: precisely mirror physical patch in 23px folded rail:
   LEFT = OUT filled 6.9px contact, RIGHT = IN 10.8px ring + 3.7px center.
   Muted idle contacts stay visible. Each direction activates independently
   with this channel's assigned color. Fixed 34x16px, no labels or effects. */
.console-body.wire-routing-v15.collapsed-send .strip .wire-fold-summary .fold-link-icon{
 width:34px!important;height:16px!important;flex:0 0 34px!important;
 display:block!important;overflow:visible;opacity:1!important;
 color:var(--ch,#8aaeb9);pointer-events:none;
}

/* Three actual physical controls, no useless fourth slot for removed X. */
.console-body.wire-routing-v15 .strip .wire-tray,
.console-body.wire-routing-v15 .strip .wire-tray.linked{
 grid-template-columns:24px 28px 22px!important;gap:4px!important;
}

/* V25 UX: compact physical WIRE, taller fader, thin selected rim,
   sharp offline Google Material SVG icons; all same strip+rail tokens. */
.console-body.wire-routing-v15:not(.collapsed-send){
 --send-h:112px!important;
}

/* V26 Focus Signal Flow — compact inspectable two-way routing ledger.
   Incoming is behind the selected channel's outgoing paths in the SAME SVG.
   No glow, no additional layer, no moving fader or rack geometry. */
.mixer-title .wire-legend{
 display:inline-flex;flex:0 1 auto;align-items:center;gap:6px;
 min-width:0;max-width:min(52vw,465px);
 margin-left:auto;padding:2px 5px;
 background:#142932;border:1px solid #38525d;border-radius:3px;
 color:#a6c4cd;font:500 9px/1.2 'Segoe UI',Arial,sans-serif;
 text-overflow:clip;overflow:hidden;white-space:nowrap;
}

/* V31 — FL-style suspended routing: actual OUT/IN/GAIN patch hardware TOP,
   the flexible signal cables hang below under their own simulated weight.
   The panel is strictly a GUI reference; don't move PAN, FX, M/S/PFL, faders.
   Reorder only expanded compartments. Folded WIRE remains 23px icon-only. */
.console-body.wire-routing-v15:not(.collapsed-send) .strip .wire-section{
 display:flex!important;flex-direction:column!important;
 justify-content:flex-start!important;
}

/* V33 compact all-bank patch picker: native keyboard accessible, no overlay. */
.mixer-title .wire-dest-picker{height:19px;min-width:118px;max-width:170px;
 background:#172b34;color:#dcf0f5;border:1px solid #54717e;border-radius:3px;
 font:500 10px/17px 'Segoe UI',Arial,sans-serif;padding:0 3px;cursor:pointer}

/* V32 off-bank patch context: visible state, not extra operator chrome. */
.mixer-title .wire-offbank-source{
 flex:none;max-width:215px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
 font:600 9px/14px 'Segoe UI',Arial,sans-serif;color:#d2f0e1;
 background:#1e3b36;border:1px solid #507f71;border-radius:3px;padding:0 5px;
 cursor:pointer;
}

/* V33 — Operator intent, tactile SEND and compact high-end console finish */
.console-body .strip .wire-node-out:not(.is-source),
.console-body .strip .wire-node-in:not(.is-source):not(.is-linked){
 color:#687881!important;border-color:#364954!important;background:#1a2c36!important;
 box-shadow:inset 0 1px 2px #07141c!important;
}

.console-body .strip .wire-tray .wire-pot:not(.is-idle)::before{
 content:""!important;inset:2px 1px!important;width:20px!important;height:20px!important;
 background:radial-gradient(circle at 35% 25%,#a9b8bf,#647b86 48%,#314956 77%,#182e39)!important;
 border:1px solid #8da4af!important;border-radius:50%!important;
 box-shadow:inset 0 1px #e5f5ff66,inset 0 -2px 2px #0b1922,0 1px 1px #030b0e!important;
}

/* Neutral dormant routing: existing connections remain in data, but no
   bright LEDs until the operator explicitly engages the SEND patch zone. */
.console-body:not(.wire-intent) .strip .wire-tray .wire-node-in,
.console-body:not(.wire-intent) .strip .wire-tray .wire-node-out{
 color:#6e7d85!important;border-color:#364854!important;
 background:#192a34!important;filter:none!important;
 box-shadow:inset 0 1px 2px #07131a!important;
}

/* V34 — Explicit WIRE arming. Mixer selection never lights routing hardware. */
.console-body:not(.wire-intent) .strip .wire-node-out,
.console-body:not(.wire-intent) .strip .wire-node-in{filter:none!important}

/* V35 exact SVG wire-pot, supplied knob-ICON.svg. One silhouette, no circular
   overlay or second indicator: its original notch acts as the pointer.
   UI selection cannot illuminate the knob; only an enabled WIRE edge can. */
.console-body.wire-routing-v15 .strip .wire-tray .wire-pot{
 background:transparent!important;border:0!important;box-shadow:none!important;
}

/* V34 Smart WIRE: overlay-only navigation. The mixer strips, cable physics,
   bank layout, meters and routing model retain their V33 geometry. */
.mixer-title .wire-v34-tool{height:19px!important;min-width:37px;padding:0 5px!important;
 border:1px solid #4b6875!important;border-radius:3px!important;
 color:#c1d7e1!important;background:#1b3541!important;
 font:600 9px/16px 'Segoe UI',Arial,sans-serif!important;flex:none}
